// 이 둘은 그대로 두세요
function loadCourse(id) {
  const COURSES = { 1: '리액트 입문', 2: 'CSS 레이아웃' };
  return new Promise((resolve, reject) => {
    setTimeout(() => {
      if (COURSES[id]) resolve({ id, name: COURSES[id] });
      else reject(new Error('코스를 찾지 못했습니다'));
    }, 60);
  });
}

function loadTeacher(courseId) {
  const TEACHERS = { 1: '김강사', 2: '박강사' };
  return new Promise((resolve, reject) => {
    setTimeout(() => {
      if (TEACHERS[courseId]) resolve(TEACHERS[courseId]);
      else reject(new Error('강사를 찾지 못했습니다'));
    }, 60);
  });
}

async function report(id) {
  try {
    const course = await loadCourse(id);
    const teacher = await loadTeacher(course.id);
    return course.name + ' · ' + teacher;
  } catch (e) {
    return '실패: ' + e.message;
  }
}
